def validate_circle_parameters(center, radius):
    """Validate circle creation parameters."""
    if not isinstance(center, (tuple, list)):
        raise ValueError("Center must be a tuple or list")

    if len(center) < 2:
        raise ValueError("Center must have at least X and Y coordinates")

    if radius <= 0:
        raise ValueError(f"Radius must be positive: {radius}")

    # Check coordinate ranges (AutoCAD limits)
    for i, coord in enumerate(center):
        if not (-1e9 <= coord <= 1e9):
            raise ValueError(f"Coordinate {i} out of valid range: {coord}")

def validate_arc_parameters(center, radius, start_angle, end_angle):
    """Validate arc creation parameters."""
    validate_circle_parameters(center, radius)

    if not isinstance(start_angle, (int, float)):
        raise ValueError("Start angle must be numeric")

    if not isinstance(end_angle, (int, float)):
        raise ValueError("End angle must be numeric")

    # Normalize angles to 0-2π range
    start_angle = start_angle % (2 * 3.14159)
    end_angle = end_angle % (2 * 3.14159)

