def run_autocad_diagnostics(): """Run comprehensive diagnostic checks for AutoCAD integration."""
diagnostics = { 'com_available': False, 'autocad_installed': False, 'connection_possible': False, 'basic_operations': False, 'memory_usage': None }
try: # Check COM availability import win32com.client import pythoncom diagnostics['com_available'] = True print("✓ COM components available")
# Check AutoCAD installation try: acad_app = win32com.client.Dispatch("AutoCAD.Application") diagnostics['autocad_installed'] = True print("✓ AutoCAD installation detected")
# Test basic connection doc = acad_app.ActiveDocument model_space = doc.ModelSpace diagnostics['connection_possible'] = True print("✓ Basic connection successful")
# Test basic operations center = win32com.client.VARIANT(pythoncom.VT_ARRAY | pythoncom.VT_R8, [0, 0, 0]) circle = model_space.AddCircle(center, 1.0) diagnostics['basic_operations'] = True print("✓ Basic geometry operations working")
# Clean up test object circle.Delete()
except Exception as e: print(f"✗ AutoCAD test failed: {e}")
except ImportError as e: print(f"✗ COM import failed: {e}")
return diagnostics
# Usage if __name__ == "__main__": results = run_autocad_diagnostics() print("\nDiagnostic Results:") for check, result in results.items(): status = "PASS" if result else "FAIL" print(f" {check}: {status}")
